contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint256 depAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depAmount)); require(depAmount <= 1000000000000000000000000000000);
        require(depAmount > 0);
        require(address(this).balance >= depAmount);
        address sender = address(this);
        uint256 balBefore = c.balances(sender); if (__ESBMC_reverted()) return;
        uint256 cBalBefore = address(c).balance;
        c.Deposit{value: depAmount}(); if (__ESBMC_reverted()) return;
        uint256 balAfter = c.balances(sender); if (__ESBMC_reverted()) return;
        uint256 cBalAfter = address(c).balance;
        assert(balAfter == balBefore + depAmount && cBalAfter == cBalBefore + depAmount);
    }
    receive() external payable {}
}

