// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ACCURAL_DEPOSIT} from "../src/ACCURAL_DEPOSIT.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ACCURAL_DEPOSIT c;

    function setUp() public {
        c = new ACCURAL_DEPOSIT();
    }

    function _run(uint256 depAmount) internal {
        depAmount = bound(depAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(depAmount > 0);
        vm.assume(address(this).balance >= depAmount);
        address sender = address(this);
        uint256 balBefore;
        try c.balances(sender) returns (uint256 __r) { balBefore = __r; } catch { return; }
        uint256 cBalBefore = address(c).balance;
        try c.Deposit{value: depAmount}() {} catch { return; }
        uint256 balAfter;
        try c.balances(sender) returns (uint256 __r) { balAfter = __r; } catch { return; }
        uint256 cBalAfter = address(c).balance;
        assertTrue(balAfter == balBefore + depAmount && cBalAfter == cBalBefore + depAmount);
    }

    function testFuzz_run(uint256 depAmount) public {
        _run(depAmount);
    }

    receive() external payable {}
}
